    function openSlashLock(
        uint256 e3Id,
        uint256 proposalId,
        address operator
    ) external onlyAuthorizedSlashingManager {
        BondingSlashingLib.openLock(
            msg.sender,
            e3Id,
            proposalId,
            operator,
            _slashRouteDestinations
        );
    }

    /// @inheritdoc IBondingRegistry
    function closeSlashLock(
        uint256 proposalId,
